import React, {useState} from 'react'
import Header from '../components/Header'
import { Container, Form } from 'react-bootstrap'
import background from '../images/helping.webp'
import axios from 'axios'

function NeedsScreen() {
  const [trainNo, setTrainNo] = useState(0)
  const handleTrainNo = (e) => {
    setTrainNo(e.target.value)
  }
  const fetchData = async () => {
    try {
      const response = await axios.get('http://localhost:8000/api/getallrequest/');
      
    } catch (error) {
      console.log('There was a problem: ', error)
    }
  }

  const handleSubmit = () => {

  }
  
  return (
    <>
      <Header/>
      <Container fluid style={{backgroundImage: `url(${background})`, backgroundRepeat: 'no-repeat', backgroundPosition: 'center', backgroundSize: 'cover', height: '100vh', opacity: 0.1}}>
        <Form onSubmit={handleSubmit}>
          <Form.Group controlId='trainNo'>
            <Form.Label><h4>Enter your Train number</h4></Form.Label>
            <Form.Control type="number" placeholder="Enter Train No" value={trainNo} onChange={handleTrainNo} />
          </Form.Group>
        </Form>
      </Container>
    </>
  )
}

export default NeedsScreen
